discrete RxSubsystem
port:
    event input real StartReceiving;
    event output real SignalReceived;
state:
    initial state IDLE
        when entry() then
            statehold(0);
        end;
        when receive(StartReceiving) then
            transition(RECEIVING);
        end;
    end;

    state RECEIVING
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(PROCESSING);
        end;
    end;

    state PROCESSING
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(READY);
            out
                send(SignalReceived, 1);
        end;
    end;

    state READY
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(IDLE);
        end;
    end;
end;
end;

